//! Generates `native/vectors.sample.json`: the reference capture **without device data**.
//!
//! The real capture (`native/vectors.json`, gitignored) comes from a test device and contains its
//! ANDROID_ID, FairPlay GUID, raw SPCs, and played track IDs. None of that belongs in the
//! repository, yet without any capture the vector tests validate nothing. This sample is the
//! middle ground: same shape, same invariants, synthetic values.
//!
//! What makes it useful is that **it is generated by the ports, not hand-pasted literals**:
//!
//! - the GUID is computed by `device_guid::build`, so the hash field is the real hash of the
//!   synthetic ANDROID_ID and `matches_android_id` verifies the algorithm;
//! - the CKC bodies are serialized by `fairplay_proto::KeyRequest::to_json`, so `keys`,
//!   `parsed`, and `raw_len` match what the app sends by construction -- including that the
//!   `offline` key is **omitted** when false, and when present its value is the string `"true"`
//!   rather than a boolean;
//! - the User-Agent is built by `store_config`.
//!
//! That is why it is not hand-written: a made-up sample could describe a body the app never
//! sends, causing the comparison test to fail because of a bad fixture.
//!
//! ```sh
//! cd native/vectors-sample && cargo run --quiet > ../vectors.sample.json
//! ```

use device_guid::{DeviceInfo, FAIRPLAY_LEN};
use fairplay_proto::{KeyRequest, Protocol};
use serde_json::{json, Map, Value};

/// Synthetic ID: 16 hex chars like a real one, clearly fabricated.
const ANDROID_ID: &str = "0123456789abcdef";
/// FairPlay field 1: 36 hex chars (18 bytes) with an easily recognizable pattern.
const FAIRPLAY_FIELD1: &str = "a1b2c3d4e5f6a1b2c3d4e5f6a1b2c3d4e5f6";

/// Deterministic base64 bytes matching the length of a trimmed real SPC.
fn synthetic_spc(seed: u8, len: usize) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let data: Vec<u8> = (0..len)
        .map(|i| (i as u8).wrapping_mul(31).wrapping_add(seed))
        .collect();
    let mut s = String::new();
    for c in data.chunks(3) {
        let b = [c[0], *c.get(1).unwrap_or(&0), *c.get(2).unwrap_or(&0)];
        let n = u32::from(b[0]) << 16 | u32::from(b[1]) << 8 | u32::from(b[2]);
        for i in 0..4 {
            if i <= c.len() {
                s.push(T[(n >> (18 - 6 * i)) as usize & 63] as char);
            } else {
                s.push('=');
            }
        }
    }
    s
}

fn main() {
    // ---- GUID, con el algoritmo del port ----
    let info = DeviceInfo {
        android_id: ANDROID_ID.to_owned(),
        serial: String::new(), // la mayoria de los Android no lo exponen
        fairplay_field1: Some(FAIRPLAY_FIELD1.to_owned()),
        fairplay_field2: None, // en el dispositivo real sale en ceros
    };
    let guid = device_guid::build(&info);
    let campos: Vec<&str> = guid.split('.').collect();
    assert_eq!(campos.len(), 6, "el GUID tiene seis campos");
    assert_eq!(campos[0].len(), FAIRPLAY_LEN, "el primer campo son 36 hex");
    assert!(
        device_guid::parse(&guid).is_some_and(|p| p.matches_android_id(ANDROID_ID)),
        "el GUID generado tiene que corresponder a su propio ANDROID_ID"
    );

    // ---- cuerpos CKC, serializados por el propio port ----
    // Una pista de streaming y una offline, para cubrir las dos ramas de `offline`.
    let pistas = [("100000001", "skd://itunes.apple.com/p1000000001/c23", false),
                  ("100000002", "skd://itunes.apple.com/p1000000002/c23", true)];
    let mut ckc_requests = Vec::new();
    let mut key_args = Vec::new();
    for (i, (adam, uri, offline)) in pistas.iter().enumerate() {
        let req = KeyRequest {
            guid: guid.clone(),
            adam_id: (*adam).to_owned(),
            key_uri: (*uri).to_owned(),
            spc_base64: synthetic_spc(i as u8 + 1, 96),
            offline: *offline,
        };
        let cuerpo = req.to_json(Protocol::Simplified).expect("to_json");
        // `keys` y `parsed` se leen de vuelta del cuerpo: asi reflejan exactamente lo que
        // el port emite, incluido que `offline` falte cuando es falso.
        let parsed: Map<String, Value> =
            serde_json::from_str(&cuerpo).expect("el cuerpo que emite el port es JSON");
        ckc_requests.push(json!({
            "raw_len": cuerpo.len(),
            "keys": parsed.keys().cloned().collect::<Vec<_>>(),
            "parsed": parsed,
        }));
        key_args.push(json!({
            "defaultId": adam,
            "adamId": adam,
            "keyUri": uri,
            "keyFormat": fairplay_proto::KEY_FORMAT,
            "keyFormatVersion": fairplay_proto::KEY_FORMAT_VERSION,
            "serverUri": fairplay_proto::KEY_SERVER_URL,
            "protocolType": fairplay_proto::PROTOCOL_SIMPLIFIED,
            "fpsCertLen": 3464,
        }));
    }

    // ---- User-Agent, from store-config ----
    // Does not identify the device: the app declares fixed "Pixel 8" everywhere it runs. Kept
    // verbatim because that is what the port must reproduce.
    let ua = store_config::RequestContextConfig::for_android(
        "/data/user/0/app.cadence/files",
        "10",
    )
    .user_agent(66);

    let salida = json!({
        "_note": "Synthetic sample generated by `cargo run` in native/vectors-sample; not from \
any device: ANDROID_ID, GUID, SPCs, and track IDs are fabricated. GUID is computed by \
device_guid::build and request bodies are serialized by fairplay_proto::to_json, so everything \
is consistent and tests validate the real algorithms. Real device captures go in \
native/vectors.json (gitignored).",
        "deviceGuidInputs": {
            "androidId": ANDROID_ID,
            "serial": Value::Null,
            "apiNum": 29,
            "forceConfig": true,
            "origin": "synthetic sample (not DeviceGUID::configure from a device)"
        },
        "deviceGuid": {
            "origin": "device_guid::build over the inputs above",
            "inputs": Value::Null,
            "guid": guid,
            "length": guid.len(),
            "fields": campos,
        },
        "ckcRequests": ckc_requests,
        "userAgent": ua,
        "getPersistentKeyArgs": key_args,
        "decryptSamples": {
            "count": 6137,
            "modes": { "5": 6137 },
            "inPlace": 6137,
            "lens": [32, 32, 2420, 9499, 8512, 10244]
        }
    });
    println!("{}", serde_json::to_string_pretty(&salida).expect("serializar"));
}
